"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[179],{3025(e){e.exports=JSON.parse('{"title":"Bun \uac1c\ubc1c\uc790\uac00 \uc124\uba85\ud558\ub294 \uc571 \ub77c\uc6b0\ud130\uc758 \ud568\uc815","date":"2025-10-28","coverUrl":"/kudzu-based-bench/assets/notion/beabf299c331fc94.png","html":"<h1 data-notion-block-id=\\"294e548d-8a8e-8058-8b3f-ee3f350a9e0a\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"299e548d-8a8e-80a8-b3e9-fbe9337e9e97\\" id=\\"299e548d-8a8e-80a8-b3e9-fbe9337e9e97\\">Bun \uac1c\ubc1c\uc790\uac00 \uc124\uba85\ud558\ub294 \uc571 \ub77c\uc6b0\ud130\uc758 \ud568\uc815</h2><a href=\\"https://paperclover.net/blog/webdev/one-year-next-app-router\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://paperclover.net/blog/webdev/one-year-next-app-router</a><p data-notion-block-id=\\"298e548d-8a8e-80f2-b9f8-d2dbb2f8a2a8\\">\uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/285e548d-8a8e-8064-b30a-f1c0548d0582#28be548d-8a8e-8052-9134-f8898c7e1f00\\">\ub2e4\ub978 Next.js\uc758 \ubd88\ud3b8\ud568\uc744 \uc778\uc9c0\ud558\uace0 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud558\ub294 \uae00</a>\uacfc \ube44\uc2b7\ud574\ubcf4\uc774\uc9c0\ub9cc, \uc774 \uae00\uc740 \uc571 \ub77c\uc6b0\ud130\ub97c \uc2e4\uc0ac\uc6a9\ud560 \ub54c \uc5b4\ub5a4 \ucf54\ub4dc \ubd80\ubd84\uc774 \ubb38\uc81c\uac00 \ub418\ub294\uc9c0, \uadf8\ub7fc\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc0ac\uc6a9\ud560\ub9cc \ud55c\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"298e548d-8a8e-808b-864d-d719da249098\\" id=\\"298e548d-8a8e-808b-864d-d719da249098\\">\ud754\ud55c \uc2e4\uc218\uc774\uc9c0\ub9cc, Promise\ub97c \uc774\ub807\uac8c \uc0ac\uc6a9\ud558\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://allthingssmitty.com/2025/10/20/rethinking-async-loops-in-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://allthingssmitty.com/2025/10/20/rethinking-async-loops-in-javascript/</a><p data-notion-block-id=\\"298e548d-8a8e-8039-9ec1-c9beaecd7ce3\\">Promise\ub97c \ucc98\uc74c \ubc30\uc6b0\uace0 \uc0ac\uc6a9\ud560 \ub54c \ub9ce\uc774 \ud558\ub294 \uc2e4\uc218\ub97c \ubcf4\uc5ec\uc8fc\uace0 \uc774\uc5d0 \ub300\ud55c \ud574\uacb0\ucc45\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uc911 <code>p-limit</code>\uc740 \uac00\ubcbc\uc6b4 \uc720\ud2f8\ub9ac\ud2f0 \ud568\uc218\ub85c \ub9ce\uc774 \uc0ac\uc6a9\ud558\ubbc0\ub85c, \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"298e548d-8a8e-80cd-be5b-ef2992e53956\\" id=\\"298e548d-8a8e-80cd-be5b-ef2992e53956\\">\ud1b5\uc81c\uad8c\uc744 \uc5bb\uc744 \uac83\uc778\uac00, \uc131\ub2a5\uacfc \uc720\uc9c0\ubcf4\uc218\uc131\uc744 \uc5bb\uc744 \uac83\uc778\uac00</h2><a href=\\"https://blog.jim-nielsen.com/2025/more-control-equals-less-performance/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.jim-nielsen.com/2025/more-control-equals-less-performance/</a><p data-notion-block-id=\\"298e548d-8a8e-8009-a808-f7373e1f3fe8\\">\uac04\ub2e8\ud55c \uc608\uc2dc\ub4e4\uc744 \ud1b5\ud574\uc11c \ube0c\ub77c\uc6b0\uc800 API/\uc0ac\uc591\uc744 \uc0ac\uc6a9\ud574\uc11c \ube0c\ub77c\uc6b0\uc800\uac00 \uc790\ub3d9\uc73c\ub85c \ud558\ub3c4\ub85d \ub450\uac8c \ub9cc\ub4e4 \uac83\uc778\uac00, \ud639\uc740 \uc5b4\ub5bb\uac8c \ud1b5\uc81c\ud560\uc9c0\ub97c \uc138\uc138\ud558\uac8c \uc218\uc815\ud560 \uac83\uc778\uac00\ub97c \uace0\ubbfc\ud558\uac8c \ub9cc\ub4dc\ub294 \uae00\uc785\ub2c8\ub2e4. \uac00\uc7a5 \ud754\ud55c \uc608\uc2dc\ub85c Scroll Snap\uc744 \uc0ac\uc6a9\ud558\uac70\ub098, \uc9c1\uc811 \uad6c\ud604\ud558\uac70\ub098, \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\uac70\ub098\uc758 \uace0\ubbfc\ub3c4 \uc788\uc744 \uac83 \uac19\ub124\uc694. Scroll Snap\uc740 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/CSS/scroll-snap-type\\">Baseline widely available\uc774 \ub41c\uc9c0</a> \uaf64 \ub410\uc73c\ub2c8\uae4c\uc694.</p><h2 data-notion-block-id=\\"298e548d-8a8e-80cb-8ae6-c2552b60571e\\" id=\\"298e548d-8a8e-80cb-8ae6-c2552b60571e\\">\uc810\uc9c4\uc801 \uc774\ubbf8\uc9c0 \ub80c\ub354\ub9c1\uc740 \uc758\ubbf8\uac00 \uc788\uc744\uae4c?</h2><a href=\\"https://jakearchibald.com/2025/present-and-future-of-progressive-image-rendering/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2025/present-and-future-of-progressive-image-rendering/</a><p data-notion-block-id=\\"299e548d-8a8e-80f4-a6d1-f2e0d417af9b\\">\uc5ec\ub7ec\uac00\uc9c0 \ud3ec\ub9f7\uc758 \uc774\ubbf8\uc9c0\uac00 \uc5b4\ub5bb\uac8c \ub80c\ub354\ub9c1\ub418\ub294\uc9c0 \uc18c\uac1c\ud558\uace0, \ud3ec\ub9f7\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc810\uc9c4\uc801\uc73c\ub85c \ub80c\ub354\ub9c1 \ub420 \uc218 \uc788\ub294\uc9c0, \ub610\ud55c \uc810\uc9c4\uc801 \ub80c\ub354\ub9c1\uc758 \uc774\uc810\uc774 \uc815\ub9d0 \uc788\ub294\uc9c0 \ud0d0\uad6c\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ubbf8\uc9c0\uc5d0 \ub300\ud55c \uae30\ubcf8 \uc9c0\uc2dd\uc744 \uc5bb\uc73c\ub824\uba74 <a href=\\"https://web.dev/learn/images\\">web.dev\uc758 \uc774\ubbf8\uc9c0 \uc139\uc158</a>\uc744 \ucc38\uace0\ud558\uc138\uc694!</p><h2 data-notion-block-id=\\"298e548d-8a8e-8034-9fbb-f448d89b188a\\" id=\\"298e548d-8a8e-8034-9fbb-f448d89b188a\\">\ubc84\ud2bc\uc774 hover\ud560 \uc218 \uc5c6\uc744 \ub54c.</h2><a href=\\"https://frontendmasters.com/blog/the-two-button-problem/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/the-two-button-problem/</a><p data-notion-block-id=\\"294e548d-8a8e-80b5-a482-cb76fe94fe28\\">\uc0ac\uc6a9\uc790\uc758 \ud658\uacbd\uc5d0 \ucee4\uc11c\uac00 \uc5c6\ub294 \uacbd\uc6b0, \ubc84\ud2bc\uc774 focus\ub418\uc5b4\uc788\ub294\uc9c0, press\ub418\uc5b4\uc788\ub294\uc9c0, \uc77c\ubc18 \uc0c1\ud0dc\uc778\uc9c0 \ud5f7\uac08\ub9ac\uac8c \ud558\ub294 UI\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ub300\ube44\ud574\uc11c \ubc84\ud2bc\uc758 \ub514\uc790\uc778\uc744 \ud55c \ubc88 \uc0dd\uac01\ud574\ubcf4\ub294 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uae00\uc5d0\uc11c\uc640 \uac19\uc774 <a href=\\"https://ones-to-watch.ethansup.net/news/post/285e548d-8a8e-8064-b30a-f1c0548d0582#285e548d-8a8e-8058-a4ce-c545c8ef6e3d\\">media query\ub97c \uc815\ud655\ud788 \uc544\ub294 \uac83</a> \ub610\ud55c \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"294e548d-8a8e-80c8-ac2c-c18f5a90872f\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"298e548d-8a8e-806d-8f7e-dec768e1b847\\" id=\\"298e548d-8a8e-806d-8f7e-dec768e1b847\\">KV \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ub9cc\ub4e4\uc5b4\ubcf4\uae30</h2><a href=\\"https://www.nan.fyi/database\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nan.fyi/database</a><p data-notion-block-id=\\"298e548d-8a8e-8069-97cf-e99fa3ac5b19\\">KV \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \ud55c \ud30c\uc77c\uc5d0\uc11c \ub2e4\ub8e8\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud574\uc11c, \uadf8\ub7ec\uba74 \uc5b4\ub5a4 \ub2e8\uc810\uc774 \ubc1c\uc0dd\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc774\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud574\uc11c \uc5b4\ub5a4 \ub3d9\uc791\ubc29\uc2dd\uc744 \ucd94\uac00\ud558\ub294\uc9c0\ub97c \ucc28\uadfc\ucc28\uadfc \ubcf4\uc5ec\uc8fc\ub294 \uc778\ud130\ub809\uc158\uc774 \ud48d\ubd80\ud55c \uae00\uc785\ub2c8\ub2e4. \uc544\uc8fc \uc27d\uac8c, \uc544\uc8fc \ucc28\uadfc\ucc28\uadfc \uc124\uba85\ud558\ubbc0\ub85c \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"29ae548d-8a8e-8050-a820-d6f73e23c966\\" id=\\"29ae548d-8a8e-8050-a820-d6f73e23c966\\">Remix Jam \uc694\uc57d\ubcf8</h2><a href=\\"https://remix.run/blog/remix-jam-2025-recap\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/remix-jam-2025-recap</a><p data-notion-block-id=\\"29ae548d-8a8e-80cd-819e-edf0151c018e\\">Remix Jam 2025\ub97c \uc694\uc57d\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \ucc57\ubd07 \ud1b5\ud569\uc744 \uc704\ud574 loader\ub97c \ud1b5\ud569\ud558\uace0 Form schema\ub97c route manifest\uc5d0 \ud1b5\ud569\ud558\ub294 \ubd80\ubd84\uc774\ub77c\ub358\uac00, \ud2b9\ud788 Remix 3\uac00 React \uae30\ubc18\uc73c\ub85c\ub9cc \ud758\ub7ec\uac00\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\ub294 \uac83\uacfc \ub2e4\ub978 UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \ud1b5\ud569\ud560 \uac83\uc774\ub77c\ub294 \uac83\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"298e548d-8a8e-80ed-89a8-def01bc2991d\\" id=\\"298e548d-8a8e-80ed-89a8-def01bc2991d\\"><code>with { type: \'json\'}</code>\uc744 \uad73\uc774 \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c?</h2><a href=\\"https://jakearchibald.com/2025/importing-vs-fetching-json/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2025/importing-vs-fetching-json/</a><h2 data-notion-block-id=\\"298e548d-8a8e-803d-990e-ed888063553d\\" id=\\"298e548d-8a8e-803d-990e-ed888063553d\\">Next.js\ub85c In-Chatgpt \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ub9cc\ub4e4\uae30</h2><a href=\\"https://vercel.com/blog/running-next-js-inside-chatgpt-a-deep-dive-into-native-app-integration\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/running-next-js-inside-chatgpt-a-deep-dive-into-native-app-integration</a><h2 data-notion-block-id=\\"294e548d-8a8e-80fb-841c-c795c214e725\\" id=\\"294e548d-8a8e-80fb-841c-c795c214e725\\">SXG \uc5f0\uad6c \uacb0\uacfc</h2><a href=\\"https://www.pawelpokrywka.com/p/my-conclusions-after-using-signed\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.pawelpokrywka.com/p/my-conclusions-after-using-signed</a><p data-notion-block-id=\\"294e548d-8a8e-80cb-a62b-cd122282d9fe\\">\uc790\uc2e0\uc758 \uc6f9\uc0ac\uc774\ud2b8\uc5d0 \ud754\uce58 \uc54a\uc740 \uae30\uc220\uc778 <a href=\\"https://web.dev/articles/signed-exchanges\\">Signed Exchanges</a>\ub97c \uc0ac\uc6a9\ud558\uace0, \uc7a5\ub2e8\uc810\uacfc \ubcf8\uc778\uc758 \uc0dd\uac01\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"298e548d-8a8e-802d-ad17-f25d916f3f48\\" id=\\"298e548d-8a8e-802d-ad17-f25d916f3f48\\">\uc0c8\ub85c\uc6b4 \uc81c\uc548: JS\uc744 \uc2e4\ud589\ud574\ub3c4 \ub418\ub294\uac00\ub97c \ud310\ub2e8\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://blog.cloudflare.com/improving-the-trustworthiness-of-javascript-on-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/improving-the-trustworthiness-of-javascript-on-the-web/</a><p data-notion-block-id=\\"298e548d-8a8e-809a-b90e-d854ce6736b4\\">\uc0c8\ub85c\uc6b4 proposal\uc744 \ud1b5\ud574\uc11c JS, CSS, WASM\uc744 \uc2e4\ud589\ud574\ub3c4 \ub418\ub294\uc9c0\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub97c \uc5b4\ub5bb\uac8c \uc5bb\uc744 \uc218 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \uae30\uc220\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc9c1 \ucd08\uc548 \ub2e8\uacc4\ub77c \uc9c0\ucf1c\ubcf4\uac70\ub098 \uc57d\uac04\uc758 \uad00\uc2ec\ub9cc \uac00\uc838\ub3c4 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"294e548d-8a8e-8061-ab7b-e45eae49ed39\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://vitest.dev/blog/vitest-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vitest.dev/blog/vitest-4</a><p data-notion-block-id=\\"299e548d-8a8e-8043-950e-c23eb833d55c\\">Vitest 4\ubc84\uc804\uc774 \ub418\uba74\uc11c playwright \uad00\ub828 \uae30\ub2a5 \uc9c0\uc6d0\uc774 \ub300\ud3ed \ucd94\uac00\ub418\uc5c8\uace0, assert \uad00\ub828 \uae30\ub2a5 \ub610\ud55c \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.youtube.com/watch?v=gjrXeqgxbas\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=gjrXeqgxbas</a><p data-notion-block-id=\\"299e548d-8a8e-8093-8623-f1c38f61be1c\\">shadcn\uc5d0\uc11c Form \uc5f0\ub3d9\uc744 React-hook-form\ub9cc \uc9c0\uc6d0\ud588\ub294\ub370, \uc774\ub97c \ud3d0\uae30\ud558\uace0 \uc5ec\ub7ec Form \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640\uc758 \uc5f0\ub3d9\uc744 \uc9c0\uc6d0\ud558\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \ub0b4\uc6a9\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.youtube.com/watch?v=QW6GECIzvsw\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=QW6GECIzvsw</a><p data-notion-block-id=\\"29ae548d-8a8e-802a-aa44-c807b7de3976\\">\ucd5c\uc2e0 CSS \uae30\ub2a5\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4.</p>"}')}}]);